-- Restricted stock is classified at creation and NEVER enters the historical
-- commercial items or replenishment streams. Conversion is not supported.
CREATE TABLE inventory_service_stock(id uuid PRIMARY KEY,program_id uuid NOT NULL,name text NOT NULL,quantity integer NOT NULL CHECK(quantity>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity),min_stock integer NOT NULL DEFAULT 0 CHECK(min_stock>=0),revision integer NOT NULL DEFAULT 1);
CREATE TABLE inventory_service_grants(id uuid PRIMARY KEY,program_id uuid NOT NULL,source_entity_id uuid NOT NULL,source_installation_id uuid NOT NULL,source_program_id uuid NOT NULL,source_module_id text NOT NULL,expires_at timestamptz NOT NULL,reason text NOT NULL,status text NOT NULL CHECK(status IN ('draft','approved','revoked')),created_by uuid NOT NULL,reviewed_by uuid,reviewed_at timestamptz,revision integer NOT NULL DEFAULT 1);
CREATE TABLE inventory_service_reservations(id uuid PRIMARY KEY,item_id uuid NOT NULL REFERENCES inventory_service_stock(id),program_id uuid NOT NULL,source_entity_id uuid NOT NULL,source_installation_id uuid NOT NULL,source_program_id uuid NOT NULL,source_module_id text NOT NULL,provider_installation_id uuid NOT NULL,package_digest text NOT NULL,grant_id uuid NOT NULL,requested integer NOT NULL,reserved integer NOT NULL CHECK(reserved>=0),consumed integer NOT NULL DEFAULT 0 CHECK(consumed>=0),status text NOT NULL CHECK(status IN ('reserved','consumed','released')));
CREATE TABLE inventory_service_movements(delivery_id uuid PRIMARY KEY,reservation_id uuid NOT NULL REFERENCES inventory_service_reservations(id),quantity integer NOT NULL CHECK(quantity>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_service_requests(request_id uuid PRIMARY KEY,actor_id uuid NOT NULL,operation text NOT NULL,digest text NOT NULL,response jsonb NOT NULL);
CREATE TABLE inventory_service_audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id text,operation text NOT NULL,status_code integer NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
